            prefix = OUTBOX_ENABLED_PREFIX,
            name = "enabled",
            havingValue = "true",
            matchIfMissing = true)
    public DomainEventOutboxStore domainEventOutboxStore(DataSource dataSource) {
        return new DomainEventOutboxStore(dataSource);
    }

